/** Independent current governance check. Never manufactures a worker or read capability. */
public final class TaskSourceVerifierSupervisorGovernance {
 private final JdbcTemplate db;private final PermissionMapper permissions;private final PermissionAuthority grants;private final PlatformMemberIdentityStatus identities;private final PermissionSchema json;private final TaskNodeProducerSchema producerSchema;private final TaskDelegationSchema delegationSchema;
 public TaskSourceVerifierSupervisorGovernance(DataSource data,PermissionMapper permissions,PermissionAuthority grants,PlatformMemberIdentityStatus identities,PermissionSchema json,TaskNodeProducerSchema producerSchema,TaskDelegationSchema delegationSchema){db=new JdbcTemplate(data);db.setQueryTimeout(5);this.permissions=permissions;this.grants=grants;this.identities=identities;this.json=json;this.producerSchema=producerSchema;this.delegationSchema=delegationSchema;}
 public void require(String tenant,String project,String run,String actor,JsonNode input,Map<String,Object> registered,JsonNode replay)throws Exception{
  var producer=rule(tenant,project,"task_source_verifier_producer",str(registered,"producer_rule_id"),str(registered,"producer_sha256"),str(registered,"producer_decision_id"),str(registered,"producer_decision_sha256"));var p=producer.required("request");
  for(String f:List.of("task_id","plan_revision","plan_sha256","role_version"))same(input.required(f),p.required(f));same(input.required("execution_policy_version"),p.required("execution_policy"));same(text(input,"snapshot_id"),text(p,"scope_snapshot"));for(var section:input.required("target_sections"))if(!TaskNodeProducerAuthority.contains(p.required("section_ids"),section.textValue()))deny();
  var delegation=rule(tenant,project,"task_delegation",text(p,"original_rule_id"),text(p,"original_rule_sha256"),null,text(p,"original_approval_sha256"));var d=delegation.required("request");for(String f:List.of("release_id","publication_approval_sha256","role_version","execution_policy","budget_revision"))same(p.required(f),d.required(f));
  same(text(p,"release_id"),text(replay,"agent_release_id"));same(text(p,"publication_approval_sha256"),text(replay,"publication_approval_sha256"));same(input.required("execution_policy_version"),replay.required("execution_policy_version"));same(text(input,"plan_revision"),text(replay,"plan_revision"));same(text(input,"replay_sha256"),hash(replay));
  requireBudget(tenant,project,run,p);requireBudget(tenant,project,run,d);requireReadActor(tenant,project,text(input,"task_id"),actor,"TASK","task.node_producer.read","TASK_NODE_PRODUCTION");requireReadActor(tenant,project,project,actor,"PROJECT","task.delegation.read","TASK_DELEGATION");
 }
 private void requireBudget(String tenant,String project,String run,JsonNode rule){
  var b=one(db.queryForList("SELECT b.spent,b.reserved,b.spent_tokens,b.reserved_tokens,b.spent_calls,b.reserved_calls,b.current_budget_revision,b.currency FROM task_run r JOIN budget_revision v ON v.tenant_id=r.tenant_id AND v.budget_revision=r.budget_revision JOIN budget_account b ON b.tenant_id=v.tenant_id AND b.budget_id=v.budget_id WHERE r.tenant_id=? AND r.project_id=? AND r.run_id=? AND r.budget_revision=? FOR UPDATE",tenant,project,run,text(rule,"budget_revision")));
  same(text(rule,"budget_revision"),str(b,"current_budget_revision"));same(text(rule,"currency"),str(b,"currency"));if(new java.math.BigDecimal(str(b,"spent")).add(new java.math.BigDecimal(str(b,"reserved"))).compareTo(new java.math.BigDecimal(text(rule,"maximum_amount")))>0)deny();for(String unit:List.of("tokens","calls"))if(new BigInteger(str(b,"spent_"+unit)).add(new BigInteger(str(b,"reserved_"+unit))).compareTo(new BigInteger(text(rule,"maximum_"+unit)))>0)deny();
 }
 private JsonNode rule(String tenant,String project,String prefix,String id,String digest,String decisionId,String decisionHash)throws Exception {
  if(!Set.of("task_source_verifier_producer","task_delegation").contains(prefix))deny();boolean producer=prefix.equals("task_source_verifier_producer");String schema=producer?producerSchema.manifest():delegationSchema.manifest();
  var row=one(db.queryForList("SELECT * FROM "+prefix+"_rule WHERE tenant_id=? AND rule_id=? FOR UPDATE",tenant,id));same(project,str(row,"project_id"));same(digest,str(row,"content_sha256"));same("1.0.0",str(row,"schema_version"));same(schema,str(row,"schema_manifest_sha256"));
  var fixed=parse(str(row,"fixed_json"));var request=fixed.required("request");if(producer){producerSchema.validate("InputAuthor",request);producerSchema.validate("InputManifest",fixed.required("manifest"));var expected=(ObjectNode)request.deepCopy();expected.remove(List.of("expected_revision","reason"));expected.put("tenant_id",tenant).put("rule_id",id).put("producer_node_kind","N05").put("purpose","TASK_NODE_PRODUCTION").put("created_by",str(row,"created_by")).put("created_at",time(row,"created_at").toInstant(ZoneOffset.UTC).toString());same(expected,fixed.required("manifest"));same(digest,hash(fixed.required("manifest")));}else {delegationSchema.validate("Author",request);same(digest,hash(fixed));}
  same(hash(request),str(row,"request_sha256"));var state=one(db.queryForList("SELECT * FROM "+prefix+"_state WHERE tenant_id=? AND rule_id=? FOR UPDATE",tenant,id));same("APPROVED",str(state,"status"));if(decisionId!=null)same(decisionId,str(state,"latest_decision_id"));
  var approval=one(db.queryForList("SELECT * FROM "+prefix+"_decision WHERE tenant_id=? AND rule_id=? AND decision_id=? FOR UPDATE",tenant,id,str(state,"latest_decision_id")));var body=parse(str(approval,"decision_json"));same(decisionHash,str(approval,"content_sha256"));same(decisionHash,hash(body));same("APPROVED",text(body,"status"));same("APPROVE",text(body.required("request"),"decision"));same(id,text(body,"rule_id"));same(digest,text(body,"rule_sha256"));same(str(state,"revision"),text(body,"revision"));same(str(approval,"created_by"),text(body,"created_by"));if(str(row,"created_by").equals(str(approval,"created_by")))deny();
  same("1.0.0",str(approval,"schema_version"));same(schema,str(approval,"schema_manifest_sha256"));same(str(row,"classification"),str(approval,"classification"));same(time(approval,"created_at").toInstant(ZoneOffset.UTC),Instant.parse(text(body,"created_at")));
  var now=permissions.databaseTime().toInstant(ZoneOffset.UTC);if(now.isBefore(Instant.parse(text(request,"valid_from")))||!now.isBefore(Instant.parse(text(request,"valid_until"))))deny();
  var scope=new PermissionProtocol.Scope(tenant,project,producer?"TASK":"PROJECT",producer?text(request,"task_id"):project);String purpose=producer?"TASK_NODE_PRODUCTION":"TASK_DELEGATION";
  actor(scope,str(row,"created_by"),text(fixed,"identity_mode"),fixed.required("grant"),producer?"task.node_producer.write":"task.delegation.author",purpose);actor(scope,str(approval,"created_by"),text(body,"identity_mode"),body.required("grant"),producer?"task.node_producer.approve":"task.delegation.approve",purpose);
  journal(row,fixed,prefix,"AUTHOR",id,project);journal(approval,body,prefix,"DECIDE",id,project);
  var parents=new TreeSet<String>(List.of(text(request,"release_id"),text(request.required("role_version"),"version_id"),text(request.required("execution_policy"),"version_id"),text(request,"budget_revision")));if(producer)for(String f:List.of("task_revision","plan_revision","template_version","scope_snapshot","original_rule_id"))parents.add(text(request,f));
  String relation=producer?"TASK_NODE_PRODUCTION":"TASK_DELEGATION_INPUT";same(List.copyOf(parents),db.query("SELECT upstream_version_id FROM lineage_edge WHERE tenant_id=? AND consumer_version_id=? AND relation_kind=? AND actor_id=? ORDER BY upstream_version_id",(rs,n)->rs.getString(1),tenant,id,relation,str(row,"created_by")));same(parents.size(),one(db.query("SELECT COUNT(*) FROM lineage_edge WHERE tenant_id=? AND consumer_version_id=?",(rs,n)->rs.getInt(1),tenant,id)));
  var version=one(db.queryForList("SELECT owner_project_id,entity_kind,content_sha256 FROM version_registry WHERE tenant_id=? AND version_id=? FOR UPDATE",tenant,id));same(project,str(version,"owner_project_id"));same(producer?"TASK_NODE_PRODUCER_RULE":"TASK_DELEGATION_RULE",str(version,"entity_kind"));same(digest,str(version,"content_sha256"));
  var result=json.object();result.set("request",request);result.set("fixed",fixed);result.set("approval",body);return result;
 }
 private void journal(Map<String,Object> row,JsonNode witness,String prefix,String kind,String id,String project)throws Exception {
  String tenant=str(row,"tenant_id"),actor=str(row,"created_by"),action=prefix.equals("task_source_verifier_producer")?"task.node_producer.":"task.delegation.";action+=prefix.equals("task_source_verifier_producer")?(kind.equals("AUTHOR")?"write":"approve"):kind.toLowerCase(Locale.ROOT);String operationPrefix=prefix.equals("task_source_verifier_producer")?"TASK-SOURCE-VERIFIER-PRODUCER-":"TASK-DELEGATION-";
  var operation=one(db.queryForList("SELECT * FROM operation_record WHERE tenant_id=? AND operation_id=? FOR UPDATE",tenant,str(row,"operation_id")));same(actor,str(operation,"subject_id"));same(operationPrefix+kind,str(operation,"operation_name"));same("COMPLETED",str(operation,"state"));same("200",str(operation,"http_status"));same(id,str(operation,"target_id"));same(str(row,"request_sha256"),str(operation,"request_sha256"));same(str(row,"idempotency_key"),str(operation,"idempotency_key"));same(parse(str(row,"receipt_json")),parse(str(operation,"response_ref")));
  var audit=one(db.queryForList("SELECT * FROM audit_event WHERE tenant_id=? AND audit_id=? FOR UPDATE",tenant,str(row,"audit_id")));var event=one(db.queryForList("SELECT * FROM outbox_event WHERE tenant_id=? AND event_id=? FOR UPDATE",tenant,str(row,"event_id")));same(actor,str(audit,"subject_id"));same(actor,str(audit,"created_by"));same(project,str(audit,"project_id"));same(action,str(audit,"action"));same("SUCCESS",str(audit,"result"));if(audit.get("reason_code")!=null)bad();same(str(row,"operation_id"),str(audit,"request_id"));same(witness,parse(str(audit,"resource_ref")));same(id,str(event,"aggregate_id"));same(action,str(event,"event_type"));same(witness,parse(str(event,"payload")));
  for(var record:List.of(operation,audit)) {same("1.0.0",str(record,"schema_version"));same(str(row,"schema_manifest_sha256"),str(record,"schema_manifest_sha256"));same(actor,str(record,"created_by"));same(str(row,"classification"),str(record,"classification"));same(time(row,"created_at"),time(record,"created_at"));}
  same(time(row,"created_at"),time(operation,"updated_at"));same("1",str(operation,"revision"));if(operation.get("error_code")!=null)bad();same(str(row,"operation_id"),str(audit,"trace_id"));same(time(row,"created_at"),time(event,"occurred_at"));same(text(parse(str(row,"receipt_json")),"revision"),str(event,"aggregate_revision"));
 }
 private void actor(PermissionProtocol.Scope scope,String actor,String mode,JsonNode original,String action,String purpose)throws Exception {activeActor(scope.tenant_id(),actor,mode);var grant=one(permissions.currentGrant(text(original,"grant_id")));if(!grant.equals(TaskFieldAuthorityWitness.grant(original)))deny();grants.requireResource(scope,actor,mode,action,purpose,List.of(grant),permissions.databaseTime());}
 private void requireReadActor(String tenant,String project,String target,String actor,String kind,String action,String purpose)throws Exception {TenantScope.requireSubjectParameter("com.ruoyi.medical.persistence.mapper.PermissionMapper.resourceGrants",Map.of("userId",actor));var binding=one(permissions.targetBinding(actor));activeActor(tenant,actor,binding.mode());grants.requireResource(new PermissionProtocol.Scope(tenant,project,kind,target),actor,binding.mode(),action,purpose,permissions.resourceGrants(actor,action),permissions.databaseTime());}
 private void activeActor(String tenant,String actor,String mode){var member=one(permissions.targetMember(actor));var binding=one(permissions.targetBinding(actor));var now=permissions.databaseTime();if(!tenant.equals(member.tenantId())||!actor.equals(member.userId())||!"ACTIVE".equals(member.status())||member.validFrom().isAfter(now)||member.validTo()!=null&&!member.validTo().isAfter(now)||!"ACTIVE".equals(binding.status())||!mode.equals(binding.mode())||!actor.equals(binding.userId())||!identities.active(new AuthenticatedIdentityBinding.View(mode,actor,binding.issuer(),binding.subject())))deny();}
 private JsonNode parse(String value)throws Exception{return producerSchema.read(value);}private static String hash(Object value)throws Exception{return WireValues.sha256(ContentReadAuthorization.canonicalBytes(value));}private static String text(JsonNode n,String f){if(!n.required(f).isTextual())bad();return n.required(f).textValue();}private static String str(Map<String,Object> r,String f){var value=r.get(f);if(value==null)bad();return value.toString();}private static LocalDateTime time(Map<String,Object> r,String f){var value=r.get(f);if(value instanceof java.sql.Timestamp t)return t.toLocalDateTime();if(value instanceof LocalDateTime t)return t;bad();return null;}private static <T>T one(List<T> rows){if(rows.size()!=1)deny();return rows.get(0);}private static void same(Object a,Object b){if(a instanceof JsonNode x&&b instanceof JsonNode y){if(!FormalTaskNodeAuthority.sameEvidence(x,y))bad();}else if(!Objects.equals(a,b))bad();}private static void bad(){throw new TenantAccessException(ErrorCode.CONTENT_MISMATCH);}private static void deny(){throw new TenantAccessException(ErrorCode.ACCESS_DENIED);}
}
